CREATE FUNCTION photo.billing_project_usage(p_tenant uuid,p_resource text,p_cursor text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE v_period uuid; v_granted bigint; v_consumed bigint; v_leased bigint; v_overrun bigint; v_revision bigint; v_id uuid;
BEGIN
 PERFORM 1 FROM photo.tenants WHERE id=p_tenant AND status='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_TENANT_INACTIVE' USING ERRCODE='P0001'; END IF;
 SELECT id INTO v_period FROM billing_periods WHERE tenant_id=p_tenant AND state='open' ORDER BY starts_at DESC LIMIT 1;
 IF NOT FOUND THEN RETURN; END IF;
 SELECT entitlement_revision INTO v_revision FROM tenant_billing_profiles WHERE tenant_id=p_tenant;
 IF NOT FOUND THEN v_revision := 1; END IF;
 SELECT COALESCE(SUM(CASE WHEN direction='credit' THEN quantity ELSE -quantity END),0) INTO v_granted
  FROM billing_resource_ledger WHERE tenant_id=p_tenant AND resource_code=p_resource AND event_type='grant';
 SELECT COALESCE(SUM(quantity),0) INTO v_consumed
  FROM billing_resource_ledger WHERE tenant_id=p_tenant AND resource_code=p_resource AND direction='debit';
 v_leased := 0; v_overrun := 0;
 SELECT id INTO v_id FROM billing_usage_summaries WHERE tenant_id=p_tenant AND resource_code=p_resource AND period_id=v_period;
 IF FOUND THEN
  UPDATE billing_usage_summaries SET granted=v_granted,consumed=v_consumed,leased=v_leased,
   available=GREATEST(v_granted-v_consumed-v_leased,0),overrun=v_overrun,
   entitlement_revision=v_revision,projected_at=clock_timestamp(),projection_cursor=p_cursor
   WHERE id=v_id;
 ELSE
  INSERT INTO billing_usage_summaries(id,tenant_id,resource_code,period_id,granted,consumed,leased,available,overrun,entitlement_revision,projected_at,projection_cursor)
   VALUES(gen_random_uuid(),p_tenant,p_resource,v_period,v_granted,v_consumed,v_leased,GREATEST(v_granted-v_consumed,0),v_overrun,v_revision,clock_timestamp(),p_cursor);
 END IF;
END $$;
