CREATE FUNCTION photo.billing_expire_buckets(p_tenant uuid,p_resource text,p_server_time timestamptz,p_cursor text,p_batch bigint) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE v_count bigint; v_new_cursor text;
BEGIN
 IF p_batch IS NULL OR p_batch<1 OR p_batch>1000 THEN RAISE EXCEPTION 'BILLING_EXPIRE_BATCH_INVALID' USING ERRCODE='P0001'; END IF;
 PERFORM photo.billing_quota_lock(p_tenant,p_resource);
 WITH expired AS (
  SELECT id FROM billing_credit_buckets
   WHERE tenant_id=p_tenant AND resource_code=p_resource
     AND expires_at IS NOT NULL AND expires_at<=p_server_time
     AND remaining_quantity>0
     AND (p_cursor IS NULL OR id::text>p_cursor)
   ORDER BY id LIMIT p_batch FOR UPDATE
 ), zeroed AS (
  UPDATE billing_credit_buckets SET remaining_quantity=0 WHERE id IN (SELECT id FROM expired)
  RETURNING id
 )
 SELECT count(*),max(id::text) INTO v_count,v_new_cursor FROM zeroed;
 IF v_count<p_batch THEN RETURN ''; END IF;
 RETURN v_new_cursor;
END $$;
