CREATE FUNCTION photo.billing_cover_overrun(p_tenant uuid,p_resource text,p_new_grant_ref uuid) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE v_overrun bigint; v_cover bigint;
BEGIN
 PERFORM photo.billing_quota_lock(p_tenant,p_resource);
 SELECT overrun_quantity INTO v_overrun FROM billing_resource_balances WHERE tenant_id=p_tenant AND resource_code=p_resource;
 IF NOT FOUND OR v_overrun<=0 THEN RETURN 0; END IF;
 SELECT least(remaining_quantity,v_overrun) INTO v_cover
  FROM billing_credit_buckets WHERE id=p_new_grant_ref AND tenant_id=p_tenant AND resource_code=p_resource FOR UPDATE;
 IF NOT FOUND OR v_cover<=0 THEN RETURN 0; END IF;
 UPDATE billing_credit_buckets SET remaining_quantity=remaining_quantity-v_cover WHERE id=p_new_grant_ref;
 UPDATE billing_resource_balances SET overrun_quantity=overrun_quantity-v_cover WHERE tenant_id=p_tenant AND resource_code=p_resource;
 RETURN v_cover;
END $$;
