CREATE FUNCTION photo.billing_rollover_bucket(p_origin_bucket_id uuid,p_next_paid_period_id uuid) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE origin billing_credit_buckets%ROWTYPE; v_transferred bigint;
BEGIN
 SELECT * INTO origin FROM billing_credit_buckets WHERE id=p_origin_bucket_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_BUCKET_NOT_FOUND' USING ERRCODE='P0001'; END IF;
 IF origin.expiry_policy<>'period_end' THEN RAISE EXCEPTION 'BILLING_BUCKET_NOT_ROLLOVER_ELIGIBLE' USING ERRCODE='P0001'; END IF;
 v_transferred := origin.remaining_quantity;
 IF v_transferred<=0 THEN RETURN 0; END IF;
 UPDATE billing_credit_buckets SET remaining_quantity=0 WHERE id=p_origin_bucket_id;
 RETURN v_transferred;
END $$;
