LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE alloc billing_usage_ticket_allocations%ROWTYPE;
BEGIN
 SELECT * INTO alloc FROM billing_usage_ticket_allocations WHERE ticket_id=p_ticket_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_TICKET_NOT_FOUND' USING ERRCODE='P0001'; END IF;
 IF alloc.settled_quantity>0 THEN RETURN; END IF;
 IF p_quantity IS NULL OR p_quantity<0 OR p_quantity>alloc.quantity
  THEN RAISE EXCEPTION 'BILLING_SETTLE_QUANTITY_INVALID' USING ERRCODE='P0001'; END IF;
 UPDATE billing_usage_ticket_allocations
  SET settled_quantity=p_quantity, released_quantity=quantity-p_quantity
  WHERE ticket_id=p_ticket_id AND settled_quantity=0;
END $$;
